// Category A — one table on a floor map. The whole tile is the press target: pressing it opens the
// table's order. A POS draws its table home as a grid of these: an empty table is its name inside an outline in the zone's colour; a seated
// table fills with that colour and lists the name, the time since seating, the first items with their
// quantities, how many more, and the total.
//
// The map itself is the consumer's Grid and the floors are Tabs, as ProductTile leaves its grid to the
// screen: a floor's layout is the owner's, so there is nothing for a Block to own.
//
// The zone colour (`zone`) is a slot of Sando's categorical palette, 1 to 8. It
// fills a seated tile under on-colour text and edges an empty one, and the system owns both contrasts:
// `fill.category.n` carries `text.on-color`, and the edge takes `border.category.n`, the same hue held
// to 3:1 on the tile's surface in every theme. Colour still is not the only carrier of the zone: name
// it in text too, in `name` or beside the map (WCAG 1.4.1). Without a zone the tile takes the brand fill.
//
// The tile's accessible name is its text in DOM order: "테이블 01, 00:17, 공기밥 2, …, 외 1개, 34,000원".
//
// ponytail: the 미결제 chip, the guest count and the grouped-table band are not here; add them when a
// screen needs them. Selection for 자리이동 and 합석 is the screen's: it changes what a press does.
import { Button as AriaButton } from "react-aria-components";
import type { ButtonProps as AriaButtonProps } from "react-aria-components";
import type { CSSProperties, ReactNode, Ref } from "react";
import "./TableTile.css";

type TableTileSize = "small" | "medium" | "large";

/** One item on a seated table. */
export interface TableTileItem {
  /** Stable key. */
  id: string;
  /** The item's name; a long one is cut with an ellipsis. */
  name: string;
  /** How many. */
  quantity: number;
}

export interface TableTileBaseProps
  extends Omit<AriaButtonProps, "className" | "style" | "children" | "onPress" | "name"> {
  /**
   * Size axis: the type rung, the inset and the minimum height.
   *
   * @default "medium"
   */
  size?: TableTileSize;
  /** The table's name, e.g. "테이블 01". */
  name: ReactNode;
  /** The zone's palette slot, 1 to 8: the empty tile's edge and the seated tile's fill. */
  zone?: 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8;
  /** Called when the tile is pressed. */
  onPress?: () => void;
}

export type TableTileProps = TableTileBaseProps &
  (
    | {
        /** The seated table's total as shown, e.g. "34,000원". Its presence marks the table seated. */
        total: string;
        /** Time since seating as shown, e.g. "00:17". */
        elapsed?: string;
        /** The order's items, first first. */
        items: TableTileItem[];
        /**
         * How many items show before the rest fold into `moreLabel`.
         *
         * @default 3
         */
        maxItems?: number;
        /** The count of folded items as shown, e.g. `(n) => \`외 ${n}개\``. */
        moreLabel: (count: number) => string;
      }
    | { total?: undefined; elapsed?: undefined; items?: undefined; maxItems?: undefined; moreLabel?: undefined }
  ) & {
    /** Additional class (optional). sd-table-tile is always preserved. */
    className?: string;
    /** Inline style for layout, e.g. a grid placement. */
    style?: CSSProperties;
    /** Forwarded to the button element. */
    ref?: Ref<HTMLButtonElement>;
  };

export function TableTile({
  size = "medium",
  name,
  zone,
  onPress,
  total,
  elapsed,
  items = [],
  maxItems = 3,
  moreLabel,
  className,
  style,
  ref,
  ...props
}: TableTileProps) {
  const occupied = total !== undefined;
  const shown = items.slice(0, maxItems);
  const more = items.length - shown.length;
  return (
    <AriaButton
      {...props}
      ref={ref}
      className={className ? `sd-table-tile ${className}` : "sd-table-tile"}
      data-size={size}
      data-occupied={occupied || undefined}
      data-zone={zone && Number.isInteger(zone) && zone >= 1 && zone <= 8 ? zone : undefined}
      style={style}
      onPress={onPress}
    >
      <span className="sd-table-tile__header" data-occupied={occupied || undefined}>
        <span className={`sd-table-tile__name sd-type-body-${size}${occupied ? "-emphasized" : ""}`}>{name}</span>
        {elapsed && <span className={`sd-table-tile__elapsed sd-type-body-${size}`}>{elapsed}</span>}
      </span>
      {shown.length > 0 && (
        <span className="sd-table-tile__items">
          {shown.map((item) => (
            <span key={item.id} className={`sd-table-tile__item sd-type-body-${size}`}>
              <span className="sd-table-tile__item-name">{item.name}</span>
              <span className="sd-table-tile__quantity">{item.quantity}</span>
            </span>
          ))}
        </span>
      )}
      {occupied && (
        <span className="sd-table-tile__footer">
          {more > 0 && moreLabel && <span className={`sd-type-caption-${size}`}>{moreLabel(more)}</span>}
          <span className={`sd-table-tile__total sd-type-body-${size}-emphasized`}>{total}</span>
        </span>
      )}
    </AriaButton>
  );
}

/* The tile fills the grid cell it is given: the header at the top, the item rows under it, the footer
   at the bottom of at least the size's minimum height, as on a POS table home. Every part is a
   flex item, so assistive technology hears a break between them. */
.sd-table-tile {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--sd-table-tile-gap);
  inline-size: 100%;
  min-inline-size: 0;
  margin: 0;
  border: var(--sd-table-tile-border-width) solid var(--sd-table-tile-border);
  background: var(--sd-table-tile-background);
  color: var(--sd-table-tile-foreground);
  /* The wash each state lays over the tile: the surface wash, or on an occupied tile's solid fill the
     one named for its ink, which goes away from that ink (contrast-contract.mjs § the state layer). */
  --sd-table-tile-state-hover-current: var(--sd-state-hover);
  --sd-table-tile-state-pressed-current: var(--sd-state-pressed);
  text-align: start;
  cursor: pointer;
  outline: none;
}
/* A zone sets the tile's edge (border.category) and seated fill (fill.category) from the palette. */
.sd-table-tile[data-zone="1"] {
  --sd-table-tile-zone-current: var(--sd-table-tile-zone-1);
  --sd-table-tile-edge-current: var(--sd-table-tile-zone-edge-1);
}
.sd-table-tile[data-zone="2"] {
  --sd-table-tile-zone-current: var(--sd-table-tile-zone-2);
  --sd-table-tile-edge-current: var(--sd-table-tile-zone-edge-2);
}
.sd-table-tile[data-zone="3"] {
  --sd-table-tile-zone-current: var(--sd-table-tile-zone-3);
  --sd-table-tile-edge-current: var(--sd-table-tile-zone-edge-3);
}
.sd-table-tile[data-zone="4"] {
  --sd-table-tile-zone-current: var(--sd-table-tile-zone-4);
  --sd-table-tile-edge-current: var(--sd-table-tile-zone-edge-4);
}
.sd-table-tile[data-zone="5"] {
  --sd-table-tile-zone-current: var(--sd-table-tile-zone-5);
  --sd-table-tile-edge-current: var(--sd-table-tile-zone-edge-5);
}
.sd-table-tile[data-zone="6"] {
  --sd-table-tile-zone-current: var(--sd-table-tile-zone-6);
  --sd-table-tile-edge-current: var(--sd-table-tile-zone-edge-6);
}
.sd-table-tile[data-zone="7"] {
  --sd-table-tile-zone-current: var(--sd-table-tile-zone-7);
  --sd-table-tile-edge-current: var(--sd-table-tile-zone-edge-7);
}
.sd-table-tile[data-zone="8"] {
  --sd-table-tile-zone-current: var(--sd-table-tile-zone-8);
  --sd-table-tile-edge-current: var(--sd-table-tile-zone-edge-8);
}
.sd-table-tile[data-zone] {
  border-color: var(--sd-table-tile-edge-current, var(--sd-table-tile-border));
}
/* Raised to `text.DEFAULT` while hovered or pressed: the resting ink is derived at its floor and
   falls under 4.5:1 over the surface wash (contrast-contract.mjs § SURFACE_WASH_INKS). */
.sd-table-tile[data-hovered]:not([data-occupied]),
.sd-table-tile[data-pressed]:not([data-occupied]) {
  color: var(--sd-table-tile-foreground-hover);
}
.sd-table-tile[data-occupied] {
  background: var(--sd-table-tile-background-occupied);
  color: var(--sd-table-tile-foreground-occupied);
  --sd-table-tile-state-hover-current: var(--sd-state-hover-on-color);
  --sd-table-tile-state-pressed-current: var(--sd-state-pressed-on-color);
}
.sd-table-tile[data-occupied][data-zone] {
  background: var(--sd-table-tile-zone-current, var(--sd-table-tile-background-occupied));
}

.sd-table-tile[data-size="small"] {
  min-block-size: var(--sd-table-tile-min-height-small);
  padding: var(--sd-table-tile-padding-small);
  border-radius: var(--sd-table-tile-radius-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-table-tile[data-size="medium"] {
  min-block-size: var(--sd-table-tile-min-height-medium);
  padding: var(--sd-table-tile-padding-medium);
  border-radius: var(--sd-table-tile-radius-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-table-tile[data-size="large"] {
  min-block-size: var(--sd-table-tile-min-height-large);
  padding: var(--sd-table-tile-padding-large);
  border-radius: var(--sd-table-tile-radius-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}

.sd-table-tile::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-table-tile[data-hovered]::after {
  background: var(--sd-table-tile-state-hover-current);
}
.sd-table-tile[data-pressed]::after {
  background: var(--sd-table-tile-state-pressed-current);
}
.sd-table-tile[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* An empty table shows only its name, centred along the top edge. */
.sd-table-tile__header {
  display: flex;
  justify-content: center;
  align-items: baseline;
  gap: var(--sd-table-tile-gap);
}
.sd-table-tile__header[data-occupied] {
  justify-content: space-between;
}

.sd-table-tile__name {
  min-inline-size: 0;
  overflow-wrap: anywhere;
}

.sd-table-tile__elapsed,
.sd-table-tile__quantity,
.sd-table-tile__total {
  flex: none;
  font-variant-numeric: tabular-nums;
}

/* The item rows read as one list, set solid; the tile's gap separates the list
   from the header and the footer. */
.sd-table-tile__items {
  display: flex;
  flex-direction: column;
}

.sd-table-tile__item {
  display: flex;
  justify-content: space-between;
  gap: var(--sd-table-tile-gap);
}

.sd-table-tile__item-name {
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sd-table-tile__footer {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: var(--sd-table-tile-gap);
  margin-block-start: auto;
}

.sd-table-tile__total {
  margin-inline-start: auto;
}
